import json
import os
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

import requests

OPENAI_API_URL = "https://api.openai.com/v1/responses"
OPENAI_MODEL = "gpt-5.4-mini"


def _as_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def _build_input(text: str, target_language: str, source_language: Optional[str]) -> str:
    parts = [
        f"Translate the following user-facing document text into {target_language}.",
    ]
    if source_language:
        parts.append(f"Source language: {source_language}.")
    parts.append("Preserve meaning, names, identifiers, numbers, dates, punctuation, and formatting as much as possible.")
    parts.append("Return only the translated text.")
    parts.append("")
    parts.append(text)
    return "\n".join(parts)


def _extract_output_text(payload: Dict[str, Any]) -> str:
    if isinstance(payload.get("output_text"), str) and payload["output_text"]:
        return payload["output_text"]
    output = payload.get("output") or []
    chunks: List[str] = []
    for item in output:
        content = item.get("content") or []
        for part in content:
            text = part.get("text")
            if isinstance(text, str):
                chunks.append(text)
    return "".join(chunks).strip()


def translate_record_fields(
    record: Dict[str, Any],
    *,
    fields: Optional[Sequence[str]] = None,
    target_language: str = "English",
    source_language: Optional[str] = None,
    api_key: Optional[str] = None,
    model: str = OPENAI_MODEL,
) -> Dict[str, Any]:
    key = api_key or os.getenv("OPENAI_API_KEY")
    if not key:
        raise ValueError("OPENAI_API_KEY is required")
    selected_fields = list(fields) if fields is not None else [
        k for k, v in record.items() if isinstance(v, str) and v.strip()
    ]
    translated = dict(record)
    for field in selected_fields:
        if field not in record:
            continue
        value = record[field]
        if not isinstance(value, str) or not value.strip():
            continue
        prompt = _build_input(value, target_language, source_language)
        response = requests.post(
            OPENAI_API_URL,
            headers={
                "Authorization": f"Bearer {key}",
                "Content-Type": "application/json",
            },
            json={
                "model": model,
                "input": prompt,
            },
            timeout=60,
        )
        response.raise_for_status()
        translated[field] = _extract_output_text(response.json()) or value
    return translated


