    records: Iterable[Dict[str, Any]],
    *,
    fields: Optional[Sequence[str]] = None,
    target_language: str = "English",
    source_language: Optional[str] = None,
    api_key: Optional[str] = None,
    model: str = OPENAI_MODEL,
) -> List[Dict[str, Any]]:
